INSERT INTO `preguntas_competencias` VALUES (21,2,1,1,1,1,'B├ísico','Resolver: 2x + 3 = 11','x=2','x=3','x=4','x=5','C','Para resolver una ecuaci├│n lineal es necesario aislar la variable. Primero se resta 3 en ambos lados de la igualdad obteniendo 2x=8 y posteriormente se divide entre 2. El resultado correcto es x=4.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(22,2,1,1,1,1,'B├ísico','Resolver: 5x = 25','x=3','x=4','x=5','x=6','C','Cuando una variable est├í multiplicada por un n├║mero, se aplica la operaci├│n inversa para despejarla. Al dividir ambos lados entre 5 se obtiene x=5.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(23,2,1,1,1,1,'B├ísico','Resolver: x - 7 = 5','x=10','x=11','x=12','x=13','C','Para despejar la variable se suma 7 en ambos lados de la ecuaci├│n. Esto conserva la igualdad y permite obtener x=12.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(24,2,1,1,1,1,'B├ísico','Resolver: 3x + 2 = 14','x=3','x=4','x=5','x=6','B','Primero se resta 2 en ambos lados de la igualdad, obteniendo 3x=12. Luego se divide entre 3 para encontrar el valor de x.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(25,2,1,1,1,1,'B├ísico','Resolver: x/2 = 6','x=8','x=10','x=12','x=14','C','Cuando una variable est├í dividida por un n├║mero, se multiplica ambos lados por dicho valor para aislarla. As├¡ se obtiene x=12.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(26,2,1,1,1,1,'B├ísico','Si f(x)=x+2, calcular f(5)','5','6','7','8','C','Una funci├│n asigna un valor de salida para cada entrada. Sustituyendo x=5 en la expresi├│n se obtiene f(5)=5+2=7.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(27,2,1,1,1,1,'B├ísico','Si f(x)=2x, calcular f(4)','6','8','10','12','B','Para evaluar una funci├│n se reemplaza la variable por el valor indicado. Al sustituir x=4 se obtiene f(4)=2├ù4=8.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(28,2,1,1,1,1,'B├ísico','Resolver: 4x - 8 = 0','x=1','x=2','x=3','x=4','B','Se suma 8 a ambos lados para obtener 4x=8. Luego se divide entre 4 para encontrar el valor de la inc├│gnita.',30,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(29,2,1,1,1,1,'Intermedio','Resolver: 2(x+3)=14','x=3','x=4','x=5','x=6','B','Primero se divide entre 2 en ambos lados de la ecuaci├│n, obteniendo x+3=7. Finalmente se resta 3 para encontrar x=4.',45,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(30,2,1,1,1,1,'Intermedio','Resolver: 3(x-2)=9','x=3','x=4','x=5','x=6','C','Se divide ambos lados entre 3 para simplificar la expresi├│n y obtener xÔêÆ2=3. Luego se suma 2 en ambos lados para hallar x=5.',45,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(31,2,1,1,1,1,'Intermedio','Si f(x)=x┬▓, calcular f(6)','30','32','34','36','D','La funci├│n cuadr├ítica eleva al cuadrado el valor de entrada. Al sustituir x=6 se obtiene 6┬▓=36.',45,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(32,2,1,1,1,1,'Intermedio','Resolver: x┬▓=49','x=5','x=6','x=7','x=8','C','La ecuaci├│n indica que el cuadrado de un n├║mero es 49. La ra├¡z cuadrada principal de 49 es 7, por lo que esa es la respuesta esperada.',45,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(33,2,1,1,1,1,'Intermedio','Hallar la pendiente entre (1,2) y (3,6)','1','2','3','4','B','La pendiente mide la variaci├│n vertical respecto a la horizontal. Aplicando la f├│rmula m=(yÔééÔêÆyÔéü)/(xÔééÔêÆxÔéü) se obtiene (6ÔêÆ2)/(3ÔêÆ1)=2.',60,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(34,2,1,1,1,1,'Intermedio','Resolver: 2x+5=3xÔêÆ1','x=4','x=5','x=6','x=7','C','Se trasladan los t├®rminos con x a un lado y las constantes al otro. Al simplificar la ecuaci├│n se obtiene x=6.',60,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(35,2,1,1,1,1,'Intermedio','Si f(x)=3xÔêÆ2, calcular f(7)','17','18','19','20','C','La evaluaci├│n de funciones consiste en reemplazar la variable por el valor indicado. Al sustituir x=7 se obtiene 3(7)ÔêÆ2=19.',60,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(36,2,1,1,1,1,'Avanzado','Resolver: x┬▓ÔêÆ9=0','x=┬▒3','x=┬▒2','x=3','x=ÔêÆ3','A','La ecuaci├│n puede reescribirse como x┬▓=9. Las soluciones son los dos n├║meros cuyo cuadrado es 9, es decir, x=3 y x=ÔêÆ3.',90,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(37,2,1,1,1,1,'Avanzado','Resolver: x┬▓ÔêÆ5x+6=0','2 y 3','1 y 6','2 y 4','3 y 5','A','El trinomio puede factorizarse como (xÔêÆ2)(xÔêÆ3)=0. Por la propiedad del producto nulo, las soluciones son x=2 y x=3.',90,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(38,2,1,1,1,1,'Avanzado','Si f(x)=2x┬▓ÔêÆ3x, calcular f(4)','18','20','22','24','B','Se sustituye x=4 en la funci├│n y se realizan las operaciones respetando el orden matem├ítico. El resultado es 2(16)ÔêÆ12=20.',90,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(39,2,1,1,1,1,'Avanzado','Resolver el sistema: x+y=10, xÔêÆy=2','x=6,y=4','x=4,y=6','x=5,y=5','x=7,y=3','A','Sumando ambas ecuaciones se elimina la variable y, obteniendo 2x=12. Luego se calcula x=6 y sustituyendo en una de las ecuaciones se obtiene y=4.',90,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(40,2,1,1,1,1,'Avanzado','Si f(x)=x┬▓ÔêÆ4x+3, hallar f(2)','ÔêÆ1','0','1','2','A','Se reemplaza x por 2 y se realizan las operaciones correspondientes. El resultado es 2┬▓ÔêÆ4(2)+3=ÔêÆ1.',90,1,'2026-06-16 04:36:11','2026-06-16 04:36:11'),(41,3,2,1,4,1,'B├ísico','┬┐Cu├ínto es 5 + 8?','11','12','13','14','C','La suma de 5 y 8 es 13.',45,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(42,3,2,1,4,1,'B├ísico','┬┐Cu├ínto es 15 - 7?','8','7','9','6','A','Al restar 7 de 15 se obtiene 8.',45,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(43,3,2,1,4,1,'B├ísico','┬┐Cu├ínto es 6 ├ù 4?','20','22','24','26','C','Multiplicar 6 por 4 da 24.',45,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(44,3,2,1,4,1,'B├ísico','┬┐Cu├ínto es 24 ├À 6?','3','4','5','6','B','24 dividido para 6 es igual a 4.',45,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(45,3,2,1,4,1,'B├ísico','Simplifique: x + x','x┬▓','2x','x','3x','B','Son t├®rminos semejantes.',60,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(46,3,2,1,4,1,'B├ísico','Simplifique: 3a + 2a','5a','6a','a┬▓','5a┬▓','A','Se suman coeficientes.',60,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(47,3,2,1,4,1,'B├ísico','Resolver: x + 5 = 9','3','4','5','6','B','Restando 5 se obtiene x=4.',60,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(48,3,2,1,4,1,'B├ísico','Resolver: x - 2 = 7','5','7','8','9','D','Sumando 2 se obtiene x=9.',60,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(49,3,2,1,4,1,'B├ísico','Simplifique: 2(x+3)','2x+3','2x+6','x+6','x+3','B','Aplicando distributiva.',60,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(50,3,2,1,4,1,'B├ísico','┬┐Cu├ínto es 7┬▓?','14','28','49','56','C','7├ù7=49.',45,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(51,3,2,1,4,1,'Intermedio','Resolver: 2x + 4 = 10','2','3','4','5','B','Restando 4 y dividiendo para 2.',75,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(52,3,2,1,4,1,'Intermedio','Resolver: 3x = 18','4','5','6','7','C','18 dividido para 3 es 6.',75,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(53,3,2,1,4,1,'Intermedio','Simplifique: x┬▓┬Àx┬│','xÔüÁ','xÔüÂ','xÔü╣','x┬▓','A','Se suman exponentes.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(54,3,2,1,4,1,'Intermedio','Simplifique: (2a)(3a)','5a','6a','6a┬▓','5a┬▓','C','Se multiplican coeficientes y variables.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(55,3,2,1,4,1,'Intermedio','Resolver: x/4 = 3','10','11','12','13','C','Multiplicando por 4.',75,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(56,3,2,1,4,1,'Intermedio','Factorice: 4x + 8','4(x+2)','8(x+1)','2(x+4)','4x(2)','A','Se extrae factor com├║n 4.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(57,3,2,1,4,1,'Intermedio','Resolver: y + 7 = 15','6','7','8','9','C','Restando 7.',75,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(58,3,2,1,4,1,'Intermedio','Resolver: 5x - 10 = 15','3','4','5','6','C','Sumando 10 y dividiendo para 5.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(59,3,2,1,4,1,'Intermedio','Simplifique: (x┬▓)┬│','xÔüÁ','xÔüÂ','xÔü╣','xÔü©','B','Se multiplican exponentes.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(60,3,2,1,4,1,'Intermedio','Resolver: 2(x-1)=8','3','4','5','6','C','Aplicando operaciones inversas.',90,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(61,3,2,1,4,1,'Avanzado','Resolver: x┬▓ - 9 = 0','┬▒2','┬▒3','┬▒4','┬▒5','B','Diferencia de cuadrados.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(62,3,2,1,4,1,'Avanzado','Factorice: x┬▓ - 25','(x-5)(x+5)','(x-25)(x+1)','(x-5)┬▓','(x+5)┬▓','A','Diferencia de cuadrados perfectos.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(63,3,2,1,4,1,'Avanzado','Resolver: x┬▓ - 4x = 0','0 y 4','1 y 4','2 y 2','0 y 2','A','Factorizando x(x-4).',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(64,3,2,1,4,1,'Avanzado','Resolver: x┬▓ - 5x + 6 = 0','1 y 6','2 y 3','3 y 6','1 y 5','B','Factorizando el trinomio.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(65,3,2,1,4,1,'Avanzado','Simplifique: (x┬▓y┬│)(xy┬▓)','x┬│yÔüÁ','x┬▓yÔüÁ','x┬│yÔüÂ','xÔü┤yÔüÁ','A','Se suman exponentes.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(66,3,2,1,4,1,'Avanzado','Resolver: 2x┬▓ - 8 = 0','┬▒1','┬▒2','┬▒3','┬▒4','B','x┬▓=4.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(67,3,2,1,4,1,'Avanzado','Factorice: x┬▓ + 7x + 12','(x+3)(x+4)','(x+2)(x+6)','(x+1)(x+12)','(x+4)┬▓','A','Producto 12 y suma 7.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(68,3,2,1,4,1,'Avanzado','Resolver: x┬▓ = 49','┬▒5','┬▒6','┬▒7','┬▒8','C','Ra├¡z cuadrada de 49.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(69,3,2,1,4,1,'Avanzado','Simplifique: (a┬│)┬▓','aÔüÁ','aÔüÂ','aÔü╣','a┬│','B','Se multiplican exponentes.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(70,3,2,1,4,1,'Avanzado','Resolver: x┬▓ - 16 = 0','┬▒2','┬▒3','┬▒4','┬▒5','C','x┬▓=16.',120,1,'2026-06-21 01:21:07','2026-06-24 03:52:56'),(71,3,2,2,5,1,'B├ísico','┬┐Cu├íntos lados tiene un tri├íngulo?','2','3','4','5','B','Un tri├íngulo siempre tiene tres lados.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(72,3,2,2,5,1,'B├ísico','┬┐Cu├íl es la unidad principal para medir longitud en el SI?','Metro','Litro','Kilogramo','Segundo','A','El metro es la unidad b├ísica de longitud.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(73,3,2,2,5,1,'B├ísico','┬┐Cu├íl es el per├¡metro de un cuadrado cuyo lado mide 6 cm?','12 cm','18 cm','24 cm','36 cm','C','El per├¡metro es la suma de los cuatro lados (6├ù4).',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(74,3,2,2,5,1,'Intermedio','Un rect├íngulo mide 8 cm de largo y 5 cm de ancho. ┬┐Cu├íl es su ├írea?','13 cm┬▓','26 cm┬▓','40 cm┬▓','80 cm┬▓','C','├ürea = largo ├ù ancho.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(75,3,2,2,5,1,'Intermedio','┬┐Cu├íl es el volumen de un cubo cuyo lado mide 3 cm?','9 cm┬│','18 cm┬│','27 cm┬│','36 cm┬│','C','Volumen = lado┬│ = 3┬│.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(76,3,2,2,5,1,'Intermedio','Un c├¡rculo tiene radio de 7 cm. ┬┐Qu├® f├│rmula permite calcular su ├írea?','¤Çr','2¤Çr┬▓','¤Çr┬▓','2¤Çr','C','El ├írea de un c├¡rculo es ¤Çr┬▓.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(77,3,2,2,5,1,'Avanzado','Un prisma rectangular mide 10 cm ├ù 5 cm ├ù 4 cm. ┬┐Cu├íl es su volumen?','90 cm┬│','150 cm┬│','180 cm┬│','200 cm┬│','D','Volumen = largo ├ù ancho ├ù alto.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(78,3,2,2,5,1,'Avanzado','Un terreno rectangular tiene un ├írea de 96 m┬▓ y un ancho de 8 m. ┬┐Cu├íl es su largo?','10 m','12 m','14 m','16 m','B','Largo = ├ürea ├À Ancho = 96 ├À 8.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(79,3,2,2,5,1,'Avanzado','┬┐Cu├íl es el ├írea total de un cubo de lado 5 cm?','100 cm┬▓','125 cm┬▓','150 cm┬▓','250 cm┬▓','C','├ürea total = 6 ├ù lado┬▓ = 6 ├ù 25.',60,1,'2026-07-08 18:09:34','2026-07-08 18:09:34'),(80,3,2,2,5,1,'B├ísico','┬┐Cu├íntos lados tiene un tri├íngulo?','2','3','4','5','B','Un tri├íngulo siempre tiene tres lados.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(81,3,2,2,5,1,'B├ísico','┬┐Cu├íl es la unidad principal para medir longitud en el SI?','Metro','Litro','Kilogramo','Segundo','A','El metro es la unidad b├ísica de longitud.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(82,3,2,2,5,1,'B├ísico','┬┐Cu├íl es el per├¡metro de un cuadrado cuyo lado mide 6 cm?','12 cm','18 cm','24 cm','36 cm','C','El per├¡metro es la suma de los cuatro lados (6├ù4).',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(83,3,2,2,5,1,'Intermedio','Un rect├íngulo mide 8 cm de largo y 5 cm de ancho. ┬┐Cu├íl es su ├írea?','13 cm┬▓','26 cm┬▓','40 cm┬▓','80 cm┬▓','C','├ürea = largo ├ù ancho.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(84,3,2,2,5,1,'Intermedio','┬┐Cu├íl es el volumen de un cubo cuyo lado mide 3 cm?','9 cm┬│','18 cm┬│','27 cm┬│','36 cm┬│','C','Volumen = lado┬│ = 3┬│.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(85,3,2,2,5,1,'Intermedio','Un c├¡rculo tiene radio de 7 cm. ┬┐Qu├® f├│rmula permite calcular su ├írea?','¤Çr','2¤Çr┬▓','¤Çr┬▓','2¤Çr','C','El ├írea de un c├¡rculo es ¤Çr┬▓.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(86,3,2,2,5,1,'Avanzado','Un prisma rectangular mide 10 cm ├ù 5 cm ├ù 4 cm. ┬┐Cu├íl es su volumen?','90 cm┬│','150 cm┬│','180 cm┬│','200 cm┬│','D','Volumen = largo ├ù ancho ├ù alto.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(87,3,2,2,5,1,'Avanzado','Un terreno rectangular tiene un ├írea de 96 m┬▓ y un ancho de 8 m. ┬┐Cu├íl es su largo?','10 m','12 m','14 m','16 m','B','Largo = ├ürea ├À Ancho = 96 ├À 8.',60,1,'2026-07-08 18:09:37','2026-07-08 18:09:37'),(88,3,2,2,5,1,'Avanzado','┬┐Cu├íl es el ├írea total de un cubo de lado 5 cm?','100 cm┬▓','125 cm┬▓','150 cm┬▓','250 cm┬▓','C','├ürea total = 6 ├ù lado┬▓ = 6 ├ù 25.',60,1,'2026-07-08 18:09:37','2026-07-09 22:25:56');
