--
-- Table structure for table `profesores`
--

DROP TABLE IF EXISTS `profesores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `profesores` (
  `id_profesor` int NOT NULL AUTO_INCREMENT,
  `nombre_profesor` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `institucion_educativa` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_nivel` int NOT NULL,
  `id_tipo_institucion` int DEFAULT NULL,
  `id_carrera` int DEFAULT NULL,
  `id_provincia` int NOT NULL,
  `id_ciudad` int NOT NULL,
  `correo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_rol` int NOT NULL,
  `estado` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ultimo_acceso` timestamp NULL DEFAULT NULL,
  `update_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_profesor`),
  UNIQUE KEY `correo` (`correo`),
  KEY `fk_profesor_nivel` (`id_nivel`),
  KEY `fk_profesor_tipo` (`id_tipo_institucion`),
  KEY `fk_profesor_carrera` (`id_carrera`),
  KEY `fk_profesor_provincia` (`id_provincia`),
  KEY `fk_profesor_ciudad` (`id_ciudad`),
  KEY `fk_profesor_rol` (`id_rol`),
  CONSTRAINT `fk_profesor_carrera` FOREIGN KEY (`id_carrera`) REFERENCES `carreras` (`id_carrera`),
  CONSTRAINT `fk_profesor_ciudad` FOREIGN KEY (`id_ciudad`) REFERENCES `ciudades` (`id_ciudad`),
